/**
 * Sales Pipeline E2E Tests — Quote → Sales Order → Invoice conversion chain
 *
 * Auth: uses storageState from tests/e2e/.auth/session.json (generated by auth.setup.ts)
 * Base URL: configured in playwright-test.config.ts (default: http://localhost:3101)
 */

import { test, expect } from '@playwright/test';

// ─────────────────────────────────────────────────────────────────────────────
// API SMOKE TESTS — verify routes exist and respond
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Sales Pipeline — API routes', () => {
  test('GET /api/accounting/customer-quotes responds', async ({ request }) => {
    const res = await request.get('/api/accounting/customer-quotes');
    // 200 = success, 401 = auth required — never 404/500
    expect([200, 401]).toContain(res.status());
  });

  test('GET /api/accounting/customer-sales-orders responds', async ({ request }) => {
    const res = await request.get('/api/accounting/customer-sales-orders');
    expect([200, 401]).toContain(res.status());
  });

  test('POST /api/accounting/customer-quotes validates missing body', async ({ request }) => {
    const res = await request.post('/api/accounting/customer-quotes', { data: {} });
    // Should reject with 400 (validation) or 401 (auth) — never silently accept
    expect([400, 401, 422]).toContain(res.status());
  });

  test('POST /api/accounting/customer-quotes-action rejects unknown action', async ({ request }) => {
    const res = await request.post('/api/accounting/customer-quotes-action', {
      data: { id: '00000000-0000-0000-0000-000000000001', action: 'unknown-action' },
    });
    expect([400, 401, 422]).toContain(res.status());
  });

  test('POST /api/accounting/customer-sales-orders-action rejects invalid action', async ({ request }) => {
    const res = await request.post('/api/accounting/customer-sales-orders-action', {
      data: { id: '00000000-0000-0000-0000-000000000001', action: 'invalid' },
    });
    expect([400, 401, 422]).toContain(res.status());
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// PAGE LOAD TESTS — verify pages render without error
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Sales Pipeline — Page routes load', () => {
  for (const route of [
    '/accounting/customer-quotes',
    '/accounting/customer-sales-orders',
  ]) {
    test(`GET ${route} returns 200 or 307`, async ({ page }) => {
      const res = await page.goto(route);
      expect([200, 307]).toContain(res?.status() ?? 0);
    });
  }
});

