test.describe('Customer Quotes — List Page', () => {
  test.setTimeout(30000);

  test('shows "Customer Quotes" heading', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');
    await expect(page.locator('h1', { hasText: /Customer Quotes/i })).toBeVisible();
  });

  test('has "New Quote" button', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');
    await expect(
      page.locator('button', { hasText: /New Quote/i }).first()
    ).toBeVisible();
  });

  test('has status filter tabs', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');
    // Tabs: all | draft | sent | accepted | declined | expired | converted
    for (const label of ['all', 'draft', 'sent', 'accepted']) {
      await expect(
        page.locator('button', { hasText: new RegExp(`^${label}$`, 'i') }).first()
      ).toBeVisible();
    }
  });

  test('has search input', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');
    await expect(
      page.locator('input[placeholder*="Search"]').first()
    ).toBeVisible();
  });

  test('page does not navigate to error URL', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');
    expect(page.url()).not.toMatch(/error/i);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// NEW QUOTE FORM
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Customer Quotes — New Quote Form', () => {
  test.setTimeout(30000);

  test('clicking "New Quote" reveals the form', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');

    await page.locator('button', { hasText: /New Quote/i }).first().click();

    // The form is an inline panel — a customer selector should appear
    await expect(
      page.locator('select').first()
    ).toBeVisible({ timeout: 5000 });
  });

  test('form has a customer dropdown (not free-text)', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');

    await page.locator('button', { hasText: /New Quote/i }).first().click();

    // Customer is a <select> element, not a bare <input type="text">
    const customerSelect = page.locator('select').first();
    await expect(customerSelect).toBeVisible({ timeout: 5000 });
    const tag = await customerSelect.evaluate((el) => el.tagName.toLowerCase());
    expect(tag).toBe('select');
  });

  test('form has date field', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');

    await page.locator('button', { hasText: /New Quote/i }).first().click();

    await expect(
      page.locator('input[type="date"]').first()
    ).toBeVisible({ timeout: 5000 });
  });

  test('form has line-item description input', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');

    await page.locator('button', { hasText: /New Quote/i }).first().click();

    // Description placeholder is set in the source
    await expect(
      page.locator('input[placeholder*="Description"]').first()
    ).toBeVisible({ timeout: 5000 });
  });

  test('clicking "New Quote" again collapses the form (toggle)', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');

    const btn = page.locator('button', { hasText: /New Quote/i }).first();
    await btn.click();
    await expect(page.locator('select').first()).toBeVisible({ timeout: 5000 });

    await btn.click();
    // Form panel should disappear
    await expect(page.locator('select').first()).not.toBeVisible({ timeout: 3000 });
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// QUOTE ACTIONS (requires existing quotes)
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Customer Quotes — Actions on existing rows', () => {
  test.setTimeout(30000);

  test('quote list table renders columns when quotes exist', async ({ page }) => {
    await page.goto('/accounting/customer-quotes');
    await page.waitForLoadState('networkidle');

    const rows = page.locator('tbody tr');
    const count = await rows.count();
    if (count === 0) {
      test.skip(); // No data to act on — skip gracefully
      return;
    }

    // Table headers should be visible
    for (const header of ['Quote', 'Customer', 'Date', 'Total', 'Status']) {
      await expect(page.locator('th', { hasText: header }).first()).toBeVisible();
    }
  });

  test('accepted quote shows "To SO" convert button', async ({ page }) => {
    await page.goto('/accounting/customer-quotes?status=accepted');
    await page.waitForLoadState('networkidle');

    const rows = page.locator('tbody tr');
    const count = await rows.count();
    if (count === 0) {
      test.skip();
      return;
    }

    // The first accepted quote row should have a "To SO" or equivalent button
    const firstRow = rows.first();
    const soBtn = firstRow.locator('button[title*="Sales Order"], button[title*="SO"], button:has-text("To SO")');
    // Button may or may not be labelled; just ensure at least one action button is present
    await expect(firstRow.locator('button').first()).toBeVisible();
    // If the SO button is present, confirm it's there
    const soBtnCount = await soBtn.count();
    if (soBtnCount > 0) {
      await expect(soBtn.first()).toBeVisible();
    }
  });

  test('draft quote row has action buttons', async ({ page }) => {
    await page.goto('/accounting/customer-quotes?status=draft');
    await page.waitForLoadState('networkidle');

    const rows = page.locator('tbody tr');
    const count = await rows.count();
    if (count === 0) {
      test.skip();
      return;
    }

    // Draft quotes should have Send / Accept / Decline action buttons
    const firstRow = rows.first();
    await expect(firstRow.locator('button').first()).toBeVisible();
  });
});

